type SkipReason =
  | { reason: "unchanged"; hash: number }
  | { reason: "noInstances" }
  | { reason: "transportUnavailable"; name: string };

type ReloadOutcome =
  | { outcome: "ok" }
  | { outcome: "throttled"; remainingSecs: number }
  | { outcome: "skipped"; why: string }
  | { outcome: "failed"; error: string };

type TraceEvent =
  | {
      kind: "configSet";
      widgetId: string;
      nonce: number;
      bytes: number;
      changed: boolean;
      skip?: { reason: "unchanged"; hash: number } | { reason: "noInstances" } | {
        reason: "transportUnavailable";
        name: string;
      };
    }
  | {
      kind: "write";
      transport: string;
      ok: boolean;
      durationMs: number;
      error?: string;
    }
  | { kind: "reload"; performed: boolean; reason: ReloadOutcome }
  | { kind: "poll"; count: number }
  | {
      kind: "render";
      instance: string;
      nonce: number;
      source: string;
      trigger: string;
      lagMs: number;
      skipped: SkippedElement[];
    };

type ActivityTokenEvent =
  | { kind: "activity"; id: string; pushToken: string }
  | { kind: "pushToStart"; pushToStartToken: string };
